MODULES = [("Γενικός διακόπτης φορτίου 4P 40 A", 4), ("Ενδεικτικές λυχνίες 3 φάσεων", 1),
           ("Απαγωγός υπερτάσεων Τ2, 3P+N", 4), ("ΔΔΡ 4P 40 A / 30 mA τύπου A × 3", 12)]


def modules_used():
    n = sum(m for _, m in MODULES)
    for c in CIRCUITS:
        n += {1: 1, 2: 2, 3: 3, 4: 4}[c["poles"]]
    n += 1                      # διακόπτης με λυχνία του boiler
    n += SPARE_MCB
    return n


