def _feed(fid):
    return [f for f in FEEDS if f["id"] == fid][0]["feed"]


def _cont(fid, med):
    """Η τροφοδοσία fid για να συνεχιστεί: το τελευταίο της σημείο παίρνει το μέσο του επόμενου τμήματος."""
    f = _feed(fid)
    return f[:-1] + [f[-1][:3] + (med,)]


