def _xy(pts):
    out = []
    for p in pts:
        q = (p[0], p[1])
        if not out or abs(q[0] - out[-1][0]) > 1e-6 or abs(q[1] - out[-1][1]) > 1e-6:
            out.append(q)
    return out


def _floor_xy(fid):
    f = _feed(fid); out = []
    for a, b in zip(f, f[1:]):
        if "floor" in (a[3] if isinstance(a[3], tuple) else (a[3],)) and abs(a[2] - ZF) < 1e-6 and abs(b[2] - ZF) < 1e-6:
            out += [(a[0], a[1]), (b[0], b[1])]
    return _xy([(q[0], q[1], 0, "") for q in out])


